async function main() {
  console.log('Adding sample posts to Strapi...\n');
  
  let successCount = 0;
  let failCount = 0;

  for (const post of samplePosts) {
    try {
      console.log(`Creating: "${post.heading}"...`);
      const result = await createPost(post);
      
      if (result) {
        successCount++;
        console.log(`✅ Created (ID: ${result.data.id})`);
        console.log(`   View at: http://localhost:3000/posts/${post.slug}\n`);
      } else {
        failCount++;
      }
    } catch (error) {
      failCount++;
      console.error(`❌ Error: ${error.message}\n`);
    }
  }

  console.log('\n--- Summary ---');
  console.log(`✅ Successfully created: ${successCount}`);
  console.log(`❌ Failed: ${failCount}`);
  console.log('\nView all posts at: http://localhost:3000');
}

main();

